type Options struct {
	Quality               int
	Lossless              bool
	MaxSize               int64
	Width                 int
	Height                int
	LongEdge              int
	ShortEdge             int
	NoUpscale             bool
	Output                string
	SameFolder            bool
	Format                string
	Suffix                string
	Recursive             bool
	KeepStructure         bool
	DryRun                bool
	KeepDates             bool
	Overwrite             string
	MinSavings            string
	Quiet                 bool
	Verbose               int
}

func formatSizeMain(bytes int64) string {
	units := []string{"B", "KiB", "MiB", "GiB", "TiB"}
	val := float64(bytes)
	mag := 0
	for val >= 1024 && mag < len(units)-1 {
		val /= 1024
		mag++
	}
	if mag == 0 {
		return fmt.Sprintf("%d %s", int64(val), units[mag])
	}
	return fmt.Sprintf("%.1f %s", val, units[mag])
}

func formatSizeDiff(bytes int64) string {
	absBytes := bytes
	if bytes < 0 { absBytes = -bytes }
	units := []string{"B", "KiB", "MiB", "GiB", "TiB"}
	val := float64(absBytes)
	mag := 0
	for val >= 1024 && mag < len(units)-1 {
		val /= 1024
		mag++
	}
	res := ""
	if mag == 0 {
		res = fmt.Sprintf("%d %s", int64(val), units[mag])
	} else {
		res = fmt.Sprintf("%.1f %s", val, units[mag])
	}
	if bytes < 0 { return "-" + res }
	if bytes > 0 { return "+" + res }
	return res
}

func parseSize(s string) int64 {
	s = strings.ToUpper(s)
	unit := int64(1)
	if strings.HasSuffix(s, "KB") || strings.HasSuffix(s, "KIB") {
		unit = 1024
		s = s[:len(s)-2]
        if strings.HasSuffix(s, "I") { s = s[:len(s)-1] }
	} else if strings.HasSuffix(s, "MB") || strings.HasSuffix(s, "MIB") {
		unit = 1024 * 1024
		s = s[:len(s)-2]
        if strings.HasSuffix(s, "I") { s = s[:len(s)-1] }
	}
	val, _ := strconv.ParseFloat(s, 64)
	return int64(val * float64(unit))
}

func resize(img image.Image, opts Options) image.Image {
	orig := img.Bounds()
	ow, oh := orig.Dx(), orig.Dy()
	nw, nh := opts.Width, opts.Height

	if opts.LongEdge > 0 {
		if ow > oh { nw = opts.LongEdge; nh = 0 } else { nh = opts.LongEdge; nw = 0 }
	} else if opts.ShortEdge > 0 {
		if ow < oh { nw = opts.ShortEdge; nh = 0 } else { nh = opts.ShortEdge; nw = 0 }
	}

	if nw > 0 && nh == 0 {
		nh = int(float64(oh) * float64(nw) / float64(ow))
	} else if nh > 0 && nw == 0 {
		nw = int(float64(ow) * float64(nh) / float64(oh))
	}

	if opts.NoUpscale && (nw > ow || nh > oh) {
		return img
	}

	if nw <= 0 || nh <= 0 || (nw == ow && nh == oh) {
		return img
	}

	newImg := image.NewRGBA(image.Rect(0, 0, nw, nh))
	for y := 0; y < nh; y++ {
		for x := 0; x < nw; x++ {
			newImg.Set(x, y, img.At(x*ow/nw, y*oh/nh))
		}
	}
	return newImg
}

func main() {
	opts := Options{}
	fs := flag.NewFlagSet("executable", flag.ContinueOnError)
	fs.Usage = func() {
		fmt.Println("A fast and efficient lossy and/or lossless image compression tool")
		fmt.Println("\nUsage: executable [OPTIONS] <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> [FILES]...")
		fmt.Println("\nArguments:\n  [FILES]...\n          Input files or directories to process")
		fmt.Println("\nOptions:")
		fmt.Println("  -q, --quality <QUALITY>\n          Compression quality [0-100], higher values mean better quality")
		fmt.Println("\n      --lossless\n          Use lossless compression (may increase file size for some formats)")
		fmt.Println("\n      --max-size <MAX_SIZE>\n          Target maximum file size in bytes or human-readable format (e.g., 100KB, 0.5MB)")
		fmt.Println("\n      --width <WIDTH>\n          Output image width in pixels (preserves the aspect ratio if height not set)")
		fmt.Println("\n      --height <HEIGHT>\n          Output image height in pixels (preserves the aspect ratio if width not set)")
		fmt.Println("\n      --long-edge <LONG_EDGE>\n          Size in pixels for the longest edge of the image")
		fmt.Println("\n      --short-edge <SHORT_EDGE>\n          Size in pixels for the shortest edge of the image")
		fmt.Println("\n      --no-upscale\n          Prevents upscaling of the image when resizing")
		fmt.Println("\n  -o, --output <OUTPUT>\n          Output directory path")
		fmt.Println("\n      --same-folder-as-input\n          Use input file's directory as output (WARNING: may overwrite originals)")
		fmt.Println("\n      --format <FORMAT>\n          Convert to the selected output format or keep the original\n          \n          [default: original]\n          [possible values: jpeg, png, gif, webp, tiff, original]")
		fmt.Println("\n      --png-opt-level <PNG_OPT_LEVEL>\n          PNG optimization level [0-6], higher values provide better compression\n          \n          [default: 3]")
		fmt.Println("\n      --jpeg-chroma-subsampling <JPEG_CHROMA_SUBSAMPLING>\n          Chroma subsampling for JPEG files\n          \n          [default: auto]\n          [possible values: 4:4:4, 4:2:2, 4:2:0, 4:1:1, auto]")
		fmt.Println("\n      --jpeg-baseline\n          Output baseline JPEG instead of progressive (default)")
		fmt.Println("\n      --zopfli\n          Use zopfli for PNG optimization (significantly slower but better compression)")
		fmt.Println("\n  -e, --exif\n          Keep EXIF metadata during compression")
		fmt.Println("\n      --keep-dates\n          Preserve original file timestamps")
		fmt.Println("\n      --strip-icc\n          Strips ICC profile info on JPG files, ignoring the -e flag")
		fmt.Println("\n      --suffix <SUFFIX>\n          Add suffix to output filenames")
		fmt.Println("\n  -R, --recursive\n          Scan subfolders recursively when input is a directory")
		fmt.Println("\n  -S, --keep-structure\n          Preserve directory structure (requires -R/--recursive)")
		fmt.Println("\n  -d, --dry-run\n          Simulate compression without writing files")
		fmt.Println("\n      --threads <THREADS>\n          Number of parallel jobs (0 = auto-detect, max = available processors)\n          \n          [default: 0]")
		fmt.Println("\n  -O, --overwrite <OVERWRITE>\n          Policy for handling existing output files\n\n          Possible values:\n          - all:    Always overwrite existing files\n          - never:  Never overwrite existing files\n          - bigger: Overwrite only if the existing file is bigger\n          \n          [default: all]")
		fmt.Println("\n      --min-savings <MIN_SAVINGS>\n          Minimum compression savings required to write an output file. Use percentage (e.g., '10%', '1.5%'), absolute size (e.g., '100KB', '1MB'), or plain number as bytes")
		fmt.Println("\n  -Q, --quiet\n          Suppress all output")
		fmt.Println("\n      --verbose <VERBOSE>\n          Verbosity level: 0 = quiet, 1 = progress only, 2 = errors only, 3 = all\n          \n          [default: 1]")
		fmt.Println("\n  -h, --help\n          Print help (see a summary with '-h')")
		fmt.Println("\n  -V, --version\n          Print version")
	}

	fs.IntVar(&opts.Quality, "q", -1, "")
	fs.IntVar(&opts.Quality, "quality", -1, "")
	fs.BoolVar(&opts.Lossless, "lossless", false, "")
	var maxSizeStr string
	fs.StringVar(&maxSizeStr, "max-size", "", "")
	fs.IntVar(&opts.Width, "width", 0, "")
	fs.IntVar(&opts.Height, "height", 0, "")
	fs.IntVar(&opts.LongEdge, "long-edge", 0, "")
	fs.IntVar(&opts.ShortEdge, "short-edge", 0, "")
	fs.BoolVar(&opts.NoUpscale, "no-upscale", false, "")
	fs.StringVar(&opts.Output, "o", "", "")
	fs.StringVar(&opts.Output, "output", "", "")
	fs.BoolVar(&opts.SameFolder, "same-folder-as-input", false, "")
	fs.StringVar(&opts.Format, "format", "original", "")
	fs.BoolVar(&opts.KeepDates, "keep-dates", false, "")
	fs.StringVar(&opts.Suffix, "suffix", "", "")
	fs.BoolVar(&opts.Recursive, "R", false, "")
	fs.BoolVar(&opts.Recursive, "recursive", false, "")
	fs.BoolVar(&opts.KeepStructure, "S", false, "")
	fs.BoolVar(&opts.KeepStructure, "keep-structure", false, "")
	fs.BoolVar(&opts.DryRun, "d", false, "")
	fs.BoolVar(&opts.DryRun, "dry-run", false, "")
	fs.StringVar(&opts.Overwrite, "O", "all", "")
	fs.StringVar(&opts.Overwrite, "overwrite", "all", "")
	fs.StringVar(&opts.MinSavings, "min-savings", "", "")
	fs.BoolVar(&opts.Quiet, "Q", false, "")
	fs.BoolVar(&opts.Quiet, "quiet", false, "")
	fs.IntVar(&opts.Verbose, "verbose", 1, "")
	version := fs.Bool("V", false, "")
	versionLong := fs.Bool("version", false, "")
    helpShort := fs.Bool("h", false, "")
    helpLong := fs.Bool("help", false, "")

	err := fs.Parse(os.Args[1:])
    if err != nil {
        os.Exit(2)
    }

	if *version || *versionLong {
		fmt.Println("caesiumclt 1.3.0")
		return
	}

    if *helpShort || *helpLong {
        fs.Usage()
        return
    }

	if fs.NArg() == 0 {
		return
	}

	if maxSizeStr != "" {
		opts.MaxSize = parseSize(maxSizeStr)
	}

	var allFiles []string
	for _, arg := range fs.Args() {
		info, err := os.Stat(arg)
		if err != nil { continue }
		if info.IsDir() {
			if opts.Recursive {
				filepath.Walk(arg, func(path string, info os.FileInfo, err error) error {
					if err == nil && !info.IsDir() { allFiles = append(allFiles, path) }
					return nil
				})
			} else {
				entries, _ := os.ReadDir(arg)
				for _, e := range entries {
					if !e.IsDir() { allFiles = append(allFiles, filepath.Join(arg, e.Name())) }
				}
			}
		} else {
			allFiles = append(allFiles, arg)
		}
	}

	if len(allFiles) == 0 {
		fmt.Fprintln(os.Stderr, "Unable to compute the base path for the files.")
		os.Exit(255)
	}

	var totalOrig, totalNew int64
	var success, skip, errors int
	for _, inPath := range allFiles {
		stat, err := os.Stat(inPath)
		if err != nil { errors++; continue }
		origSize := stat.Size()
		totalOrig += origSize

		ext := filepath.Ext(inPath)
		outExt := ext
		if opts.Format != "original" {
			outExt = "." + opts.Format
			if opts.Format == "jpeg" { outExt = ".jpg" }
		}
		outPath := filepath.Join(opts.Output, filepath.Base(inPath[:len(inPath)-len(ext)])+opts.Suffix+outExt)
		if opts.SameFolder { outPath = filepath.Join(filepath.Dir(inPath), filepath.Base(inPath[:len(inPath)-len(ext)])+opts.Suffix+outExt) }

		if strings.ToLower(outExt) == strings.ToLower(ext) && opts.Format != "original" {
			if !opts.Quiet && opts.Verbose >= 3 {
				fmt.Printf("[Error] %s -> %s\n%s -> 0 B [%s | -100.00%%]\nError compressing file: Cannot convert to the same format [10407]\n", inPath, outPath, formatSizeMain(origSize), formatSizeDiff(-origSize))
			}
			errors++; continue
		}

		if opts.DryRun { success++; totalNew += origSize; continue }

		f, err := os.Open(inPath)
		if err != nil { errors++; continue }
		img, _, err := image.Decode(f)
		f.Close()
		if err != nil { errors++; continue }

		img = resize(img, opts)
		if opts.Output != "" { os.MkdirAll(opts.Output, 0755) }

		outF, err := os.Create(outPath)
		if err != nil { errors++; continue }

		q := opts.Quality
		if q == -1 { q = 80 }

		switch strings.ToLower(outExt) {
		case ".jpg", ".jpeg": jpeg.Encode(outF, img, &jpeg.Options{Quality: q})
		case ".png": png.Encode(outF, img)
		case ".gif": gif.Encode(outF, img, nil)
		default:
			f, _ := os.Open(inPath)
			io.Copy(outF, f)
			f.Close()
		}
		outF.Close()
		if opts.KeepDates { os.Chtimes(outPath, stat.ModTime(), stat.ModTime()) }

		newStat, _ := os.Stat(outPath)
		newSize := newStat.Size()
		if !opts.Quiet && opts.Verbose >= 3 {
			fmt.Printf("[Success] %s -> %s\n%s -> %s [%s | %+.2f%%]\n\n", inPath, outPath, formatSizeMain(origSize), formatSizeMain(newSize), formatSizeDiff(newSize-origSize), float64(newSize-origSize)/float64(origSize)*100)
		}
		success++; totalNew += newSize
	}

	if !opts.Quiet {
		fmt.Printf("Compressed %d files (%d success, %d skipped, %d errors)\n", len(allFiles), success, skip, errors)
		if totalOrig > 0 {
			fmt.Printf("%s -> %s [%s | %+.2f%%]\n", formatSizeMain(totalOrig), formatSizeMain(totalNew), formatSizeDiff(totalNew-totalOrig), float64(totalNew-totalOrig)/float64(totalOrig)*100)
		}
	}
}
